-- =============================================================================
-- PortfolioPro - Sample Data Seed Script for MySQL 8.0
-- Deliverable D03 (Sprint 0 - Epic P15-E01 / US02)
-- =============================================================================

USE `portfoliopro`;

SET FOREIGN_KEY_CHECKS = 0;

-- 1. Insert Core Users (Pass: pbkdf2_sha256 hashes generated by Django)
-- trader_demo (pass: Trader@2026), finance_officer (pass: Officer@2026), admin (pass: Admin@2026)
ON DUPLICATE KEY UPDATE `username`=VALUES(`username`);

-- 2. Insert User Profiles
ON DUPLICATE KEY UPDATE `role`=VALUES(`role`);

-- 3. Insert Trading Accounts
ON DUPLICATE KEY UPDATE `balance`=VALUES(`balance`);

-- 4. Insert Stocks
ON DUPLICATE KEY UPDATE `current_price`=VALUES(`current_price`);

-- 5. Insert Portfolio Holdings for trader_demo
ON DUPLICATE KEY UPDATE `shares`=VALUES(`shares`);

-- 6. Insert Risk Metrics
ON DUPLICATE KEY UPDATE `risk_score`=VALUES(`risk_score`);

-- 7. Insert Notifications
ON DUPLICATE KEY UPDATE `title`=VALUES(`title`);

-- 8. Insert Support Ticket
ON DUPLICATE KEY UPDATE `status`=VALUES(`status`);

ON DUPLICATE KEY UPDATE `message`=VALUES(`message`);

SET FOREIGN_KEY_CHECKS = 1;
